func TestWithdraw(t *testing.T) {
	tests := map[string]struct {
		amount, want int
		ok           bool
	}{
		"within balance": {30, 70, true},
		"over balance":   {500, 0, false},
	}
	for name, tc := range tests {
		t.Run(name, func(t *testing.T) {
			acct := NewAccount(100)                       // Arrange
			got, err := acct.Withdraw(tc.amount)          // Act
			if (err == nil) != tc.ok || got != tc.want {  // Assert
				t.Errorf("Withdraw(%d) = %d, %v; want %d, ok=%v", tc.amount, got, err, tc.want, tc.ok)
			}
		})
	}
}
